INSERT INTO bridging.notes (id, topic_id, subtopic_name, summary, key_concepts, formulas, worked_examples, common_mistakes, exam_tips, related_topic_codes, order_index, level_band, recommended_levels, curriculum_stage, strand, estimated_minutes, revision_status, created_at, updated_at) VALUES ('019fa77e-4a20-77c9-9dbd-84e3b0a7ecaf'::uuid, '019f9df7-a2a2-7853-96ff-2c02dc5e1f10'::uuid, 'Expansion and factorisation', 'Expand by multiplying every term; factorise by extracting common factors or recognising identities. Only like terms can be combined.', ARRAY['Only like terms can be added or subtracted (e.g. 2x + 3x = 5x)', 'Expand by multiplying the outside term (or each term) through every term in the bracket', 'Factorisation reverses expansion: take out the HCF, use identities, grouping, or the cross method']::text[], ARRAY['{"note":"Spot these before using the general rainbow/FOIL method.","label":"Perfect square and difference of squares","expression":"(a + b)^2 = a^2 + 2ab + b^2; (a - b)^2 = a^2 - 2ab + b^2; a^2 - b^2 = (a + b)(a - b)"}'::jsonb]::text[], ARRAY['{"steps":["(3x + 5)^2 = 9x^2 + 2(3x)(5) + 25 = 9x^2 + 30x + 25","(x + 5)(x - 5) = x^2 - 25"],"answer":"9x^2 + 30x + 25; x^2 - 25","question":"Expand (3x + 5)^2 and (x + 5)(x - 5)."}'::jsonb, '{"steps":["49 - 4x^2 = 7^2 - (2x)^2 = (7 - 2x)(7 + 2x)","2a^2 - 8a = 2a(a - 4)"],"answer":"(7 - 2x)(7 + 2x); 2a(a - 4)","question":"Factorise completely 49 - 4x^2 and 2a^2 - 8a."}'::jsonb]::text[], ARRAY['{"fix":"Include the middle term 2ab.","mistake":"Writing (a + b)^2 as a^2 + b^2."}'::jsonb, '{"fix":"Only like terms (same letters and powers) can be added or subtracted.","mistake":"Combining unlike terms such as 3x and 5."}'::jsonb]::text[], ARRAY['Expand your factorised answer mentally to check it.', 'Completely usually means take out a common factor and then factorise further.']::text[], ARRAY['t06']::text[], 401, NULL, NULL, 'O-Level', NULL, NULL, 'published', NULL::timestamptz, '2026-07-28T06:51:39.424Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.notes (id, topic_id, subtopic_name, summary, key_concepts, formulas, worked_examples, common_mistakes, exam_tips, related_topic_codes, order_index, level_band, recommended_levels, curriculum_stage, strand, estimated_minutes, revision_status, created_at, updated_at) VALUES ('019fa77e-4a20-7a03-898c-3b69d3499409'::uuid, '019f9df7-a2a2-7853-96ff-2c02dc5e1f10'::uuid, 'Algebraic fractions and changing the subject', 'Combine algebraic fractions over a common denominator, and rearrange formulas so the required letter stands alone on the LHS.', ARRAY['Factorise denominators before finding a common denominator; cancel factors only', 'Changing the subject means isolating one letter alone on the LHS', 'Square roots give +/- answers unless the context (e.g. distance) rejects the negative']::text[], ARRAY['{"note":"Simplify the result if possible.","label":"Adding fractions","expression":"a/b + c/d = (ad + bc) / bd"}'::jsonb]::text[], ARRAY['{"steps":["Divide both sides by m: E/m = c^2","Square root both sides: c = +/- sqrt(E/m)"],"answer":"c = +/- sqrt(E/m)","question":"Make c the subject of E = mc^2."}'::jsonb, '{"steps":["Multiply both sides by 2: 2E = mv^2","Divide by v^2: m = 2E / v^2"],"answer":"m = 2E / v^2","question":"Make m the subject of E = (1/2)mv^2."}'::jsonb]::text[], ARRAY['{"fix":"Only cancel a factor common to the whole numerator and denominator.","mistake":"Cancelling the x in (x + 3)/x."}'::jsonb, '{"fix":"Include both signs unless the question rejects negatives (e.g. length).","mistake":"Dropping the +/- when taking a square root in changing the subject."}'::jsonb]::text[], ARRAY['Undo operations in reverse order: clear fractions, isolate the powered term, then take roots.', 'When the new subject appears twice, collect those terms and factorise it out.']::text[], ARRAY['t06']::text[], 402, NULL, NULL, 'O-Level', NULL, NULL, 'published', NULL::timestamptz, '2026-07-28T06:51:39.424Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.notes (id, topic_id, subtopic_name, summary, key_concepts, formulas, worked_examples, common_mistakes, exam_tips, related_topic_codes, order_index, level_band, recommended_levels, curriculum_stage, strand, estimated_minutes, revision_status, created_at, updated_at) VALUES ('019fa798-94cc-7fb5-ade9-4a1dcec6c8f9'::uuid, '019f9df7-a2a2-7853-96ff-2c02dc5e1f10'::uuid, 'Number patterns and the nth term', 'A linear sequence increases by the same amount each time, and its nth term takes the form an + b.', ARRAY['The common difference is the amount added each time and becomes the coefficient of n', 'Check your nth term by substituting n = 1 to see if it gives the first term', 'The nth term lets you jump straight to any term without listing them all', 'A decreasing sequence has a negative common difference']::text[], ARRAY['{"note":"a is the common difference and b adjusts the first term.","label":"Linear sequence","expression":"T_n = an + b"}'::jsonb, '{"note":"Because T_1 = a + b.","label":"Finding b","expression":"b = first term - a"}'::jsonb]::text[], ARRAY['{"steps":["The common difference is 3, so a = 3","b = first term - a = 5 - 3 = 2","So T_n = 3n + 2","T_20 = 3(20) + 2"],"answer":"T_n = 3n + 2 and the 20th term is 62","question":"Find the nth term of 5, 8, 11, 14, 17 and hence find the 20th term."}'::jsonb]::text[], ARRAY['{"fix":"3n alone gives 3, 6, 9. The + 2 shifts it to 5, 8, 11.","mistake":"Writing the nth term as 3n when the sequence starts at 5."}'::jsonb, '{"fix":"Check the differences are all equal first. If they are not, an + b will not work.","mistake":"Assuming every sequence is linear."}'::jsonb]::text[], ARRAY['Always test your nth term with n = 1 and n = 2 before using it.', 'For a decreasing sequence a is negative, so expect a minus sign.']::text[], ARRAY['t06']::text[], 403, NULL, NULL, 'O-Level', NULL, NULL, 'published', NULL::timestamptz, '2026-07-28T07:20:22.476Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.notes (id, topic_id, subtopic_name, summary, key_concepts, formulas, worked_examples, common_mistakes, exam_tips, related_topic_codes, order_index, level_band, recommended_levels, curriculum_stage, strand, estimated_minutes, revision_status, created_at, updated_at) VALUES ('019fa77e-4a20-7a3a-8806-6eebbef428fd'::uuid, '019f9df7-a2a2-7865-ab8c-df9bc214c173'::uuid, 'Linear graphs and gradients', 'Every non-vertical straight line can be written as y = mx + c, where m is the gradient and c is the y-intercept.', ARRAY['Gradient m = (y2 - y1) / (x2 - x1); a vertical line has undefined gradient', 'c is the value of y when x = 0', 'Parallel lines share the same gradient']::text[], ARRAY['{"note":"Keep the order of subtraction consistent.","label":"Gradient from two points","expression":"m = (y2 - y1) / (x2 - x1)"}'::jsonb, '{"note":"If the line is vertical, write it as x = k.","label":"Equation of a line","expression":"y = mx + c"}'::jsonb]::text[], ARRAY['{"steps":["m = (-9 - (-5)) / (-1 - 3) = (-4) / (-4) = 1","Substitute (-1, -9): -9 = 1(-1) + c, so c = -8","Equation: y = x - 8"],"answer":"y = x - 8","question":"A is (3, -5) and B is (-1, -9). Find the equation of line AB."}'::jsonb]::text[], ARRAY['{"fix":"Gradient is change in y over change in x.","mistake":"Computing gradient as change in x over change in y."}'::jsonb, '{"fix":"If you start with point 2 on top, start with point 2 on the bottom too.","mistake":"Mixing the order of points in numerator and denominator."}'::jsonb]::text[], ARRAY['Rearrange given equations into y = mx + c to read the gradient quickly.', 'Read the axis scales carefully before measuring a gradient off a graph.']::text[], ARRAY['t14']::text[], 501, NULL, NULL, 'O-Level', NULL, NULL, 'published', NULL::timestamptz, '2026-07-28T06:51:39.424Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.notes (id, topic_id, subtopic_name, summary, key_concepts, formulas, worked_examples, common_mistakes, exam_tips, related_topic_codes, order_index, level_band, recommended_levels, curriculum_stage, strand, estimated_minutes, revision_status, created_at, updated_at) VALUES ('019fa77e-4a20-7a59-a2f1-9b582ffbba2f'::uuid, '019f9df7-a2a2-7865-ab8c-df9bc214c173'::uuid, 'Quadratic and other graph shapes', 'Recognise graph shapes from equations. For quadratics, the line of symmetry passes through the turning point (minimum or maximum).', ARRAY['a > 0 gives a U-shaped quadratic (minimum); a < 0 gives an n-shape (maximum)', 'Line of symmetry is midway between the roots; turning point lies on it', 'Completed-square form y = (x - h)^2 + k shows the turning point (h, k) directly', 'Other shapes: cubic, reciprocal y = a/x (axes as asymptotes), exponential y = a^x']::text[], ARRAY['{"note":"Turning point is (h, k).","label":"Completed square form","expression":"y = (x - h)^2 + k"}'::jsonb, '{"note":"Does not meet the axes; a < 0 reflects into other quadrants.","label":"Reciprocal graph","expression":"y = a / x"}'::jsonb]::text[], ARRAY['{"steps":["Roots when y = 0: x = 5 or x = -1, so intercepts (5, 0) and (-1, 0)","Expand or put x = 0: y-intercept (0, 5)","x of turning point = (5 + (-1)) / 2 = 2; y = -(2 - 5)(2 + 1) = 9","Line of symmetry x = 2; maximum at (2, 9) since a < 0"],"answer":"Intercepts (5,0), (-1,0), (0,5); turning point (2,9); line x = 2","question":"For y = -(x - 5)(x + 1), find the x-intercepts, y-intercept, turning point and line of symmetry."}'::jsonb, '{"steps":["x^2 - 4x + 4 + 5 - 4 = (x - 2)^2 + 1","Minimum point (2, 1) because a > 0"],"answer":"(x - 2)^2 + 1","question":"Express x^2 - 4x + 5 in the form (x - h)^2 + k."}'::jsonb]::text[], ARRAY['{"fix":"The x-coordinate is +2; the sign inside the bracket flips.","mistake":"Reading the turning point of (x - 2)^2 + 1 as (-2, 1)."}'::jsonb, '{"fix":"Draw a single smooth curve through the points.","mistake":"Joining plotted points with straight lines on a curve."}'::jsonb]::text[], ARRAY['Identify the shape from the equation before plotting.', 'Label axes and write the equation beside each sketch.']::text[], ARRAY['t06']::text[], 502, NULL, NULL, 'O-Level', NULL, NULL, 'published', NULL::timestamptz, '2026-07-28T06:51:39.424Z'::timestamptz) ON CONFLICT (id) DO NOTHING;